        File file = new File("source_video.mp4");
        if (!file.exists()) {
            InputStream in = new URL(url).openStream();
            Files.copy(in, file.toPath(), StandardCopyOption.REPLACE_EXISTING);
        }
        return file.getAbsolutePath();
    }

    private static void initializeEncoder(FFmpegFrameGrabber grabber, FFmpegFrameRecorder recorder, int codecCase) {
        // video
        switch (codecCase) {
            case 1:
                recorder.setVideoCodecName("libx264");
                recorder.setVideoOption("profile", "main");
                recorder.setVideoOption("level", "4");
                break;
            case 2:
                // relates to Use locking callback from ffmpeg using a Java locking mechanism. #770
                // https://github.com/bytedeco/javacv/issues/770
                // test https://github.com/bytedeco/javacv/blob/master/platform/src/test/java/org/bytedeco/javacv/FrameGrabberTest.java#L128
                recorder.setPixelFormat(avutil.AV_PIX_FMT_BGR24);
                recorder.setVideoCodecName("libx264rgb");
                break;
            default:
                break;
        }

        recorder.setFrameRate(grabber.getFrameRate());
        recorder.setVideoBitrate(grabber.getVideoBitrate());
        recorder.setVideoOption("threads", "4");
        // audio
        recorder.setSampleRate(grabber.getSampleRate());
        recorder.setAudioBitrate(grabber.getAudioBitrate());
        recorder.setAudioCodec(grabber.getAudioCodec());
    }
}
