description:
On 3.12, when a Java client sends an executor to 3 nodes, it is serialized 3 times not once.

Reproducer:

```
import java.io.IOException;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

import com.hazelcast.client.HazelcastClient;
import com.hazelcast.config.Config;
import com.hazelcast.core.Hazelcast;
import com.hazelcast.core.HazelcastInstance;
import com.hazelcast.core.HazelcastInstanceAware;
import com.hazelcast.nio.ObjectDataInput;
import com.hazelcast.nio.ObjectDataOutput;
import com.hazelcast.nio.serialization.DataSerializable;

public class Reproducer {

	public static void main(String[] args) throws Exception {
		MyRunnable myRunnable = new MyRunnable();
		
		Config config = new Config();
		config.getNetworkConfig().getJoin().getMulticastConfig().setEnabled(false);
		config.getNetworkConfig().getJoin().getTcpIpConfig()
			.setMembers(Arrays.asList("127.0.0.1")).setEnabled(true);
		
		Hazelcast.newHazelcastInstance(config.setInstanceName("first"));
		Hazelcast.newHazelcastInstance(config.setInstanceName("second"));
		Hazelcast.newHazelcastInstance(config.setInstanceName("third"));
		Hazelcast.newHazelcastInstance(config.setInstanceName("fourth"));
		
		HazelcastInstance client = HazelcastClient.newHazelcastClient();

		while (client.getCluster().getMembers().size() != 4) {
			TimeUnit.SECONDS.sleep(1);
		}
		
		client.getExecutorService("default").executeOnAllMembers(myRunnable);
	}

	static class MyRunnable implements Runnable, HazelcastInstanceAware, DataSerializable {
		@Override
		public void run() {
		}

		@Override
		public void writeData(ObjectDataOutput out) throws IOException {
			System.out.println("Serialize " + this);
		}

		@Override
		public void readData(ObjectDataInput in) throws IOException {
			System.out.println("De-serialize " + this);
		}

		@Override
		public void setHazelcastInstance(HazelcastInstance hazelcastInstance) {
			System.out.println("setHazelcastInstance(" + hazelcastInstance.getName() + ") " + this);
		}
	}
}
```

