My setup: 
- Java 11 
- Hazelcast 3.12 Snapshot 
- Hazelcast Jet 3.0 Snapshot (I can't revert to previous version, it will break my logic; I need n:m joins which will be added in 3.1) 
- CPU cores: 4 
- RAM: 7 GB 
- Jet mode: server, connects to other cluster as a client to insert final data

Simple repro:
```
import com.hazelcast.core.IMap;
import com.hazelcast.jet.Jet;
import com.hazelcast.jet.JetInstance;
import com.hazelcast.jet.core.JobStatus;
import com.hazelcast.jet.pipeline.Pipeline;
import com.hazelcast.jet.pipeline.Sources;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.stream.Collectors;

import static com.hazelcast.jet.aggregate.AggregateOperations.summingDouble;
import static com.hazelcast.jet.pipeline.Sinks.logger;
import static java.math.RoundingMode.HALF_UP;
import static java.util.stream.Collectors.groupingBy;

public class JobStuckingReproducer {

    private static final int NUMBER_OF_JOBS = 30;
    private static volatile boolean shouldRun = true;

    public static void main(String[] args) throws ExecutionException, InterruptedException {
        JetInstance jet = Jet.newJetInstance();
        List<IMap<Integer, Integer>> maps = new ArrayList<>();
        for (int i = 0; i < NUMBER_OF_JOBS; i++) {
            var map = jet.<Integer, Integer>getMap("map" + i);
            for (int j = 0; j < 10_000; j++) {
                map.put(j, j);
            }
            maps.add(map);
        }

        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (int i = 0; i < NUMBER_OF_JOBS; i++) {
            var map = maps.get(i);
            Pipeline p = Pipeline.create();
            p.drawFrom(Sources.map(map))
                    .map(e -> {
                        var bd = new BigDecimal(e.getValue());

                        return bd.pow(11).subtract(bd.divide(new BigDecimal(19), HALF_UP)); // simulate any CPU usage
                    })
                    .groupingKey(e -> e.setScale(0, HALF_UP).intValue() % 10)
                    .aggregate(summingDouble(e -> e.doubleValue()))
                    .drainTo(logger());

            var job = jet.newJob(p);
            futures.add(job.getFuture());
        }

        new Thread(() -> {
            while (shouldRun) {
                try {
                    Thread.sleep(2000);

                    var jobByStatus = jet.getJobs().stream().collect(groupingBy(e -> e.getStatus(), Collectors.counting()));
                    for (JobStatus status : jobByStatus.keySet()) {
                        System.out.println("\t" + status + " -> " + jobByStatus.get(status));
                    }
                    System.out.println("in total: " + jet.getJobs().size());
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
            }
        }, "jet-jobs-printer").start();

        var combined = CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));

        combined.get();
        shouldRun = false;
        jet.shutdown();
    }
}
```

