package examples;

import org.mapdb.DB;
import org.mapdb.DBMaker;
import org.mapdb.HTreeMap;
import org.mapdb.Serializer;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Random;


public class Benchmark {

    public static void main(String[] args) throws IOException, InterruptedException {



        DB db = DBMaker.newMemoryDirectDB()
                .transactionDisable()
                .cacheDisable()
                .make();


        final HTreeMap map = db.createHashMap("test")
                .keySerializer(Serializer.STRING_ASCII)
                .valueSerializer(Serializer.STRING_ASCII)
                .expireMaxSize(5000000) // 5000000
                .make();

        int keySize = 32;
        int valSize = 512;
        int threadNum =6;
        final int numIter = 1000000;

        StringBuffer sb = new StringBuffer();
        sb.setLength(0);
        for (int i = 0; i < keySize; i++) sb.append("x");
        final String key = sb.toString();

        sb.setLength(0);
        for (int i = 0; i < valSize; i++) sb.append("x");
        final String val = sb.toString();

        long time = System.currentTimeMillis();

        Runnable r = new Runnable() {
            @Override
            public void run() {
                Random r = new Random();
                for (int i = 1; i <= numIter; i++) {
                    String key2 = key
                            +i;
                    map.put(key2, i+val);

                }
            }
        };

        ArrayList<Thread> t = new ArrayList<Thread>();

        for(int i=0;i<threadNum;i++){
            Thread t1 = new Thread(r);
            t1.start();
            t.add(t1);
        }


        for(Thread t1:t){
            t1.join();
        }

        System.out.printf("second %,d\n",System.currentTimeMillis()-time);
        db.close();

    }
}
